/* ---------- Design tuner ---------- */
.dtx{display:grid;grid-template-columns:1fr 280px;gap:14px;align-items:stretch}
@media (max-width:720px){.dtx{grid-template-columns:1fr}}
@container (max-width:600px){.dtx{grid-template-columns:1fr}.dtx-prev{min-height:240px}}
.dtx-prev{border-radius:18px;background:var(--chip);display:grid;place-items:center;padding:24px;min-height:300px;min-width:0}
.dtx-card{--rad:16px;--pad:18px;--gap:12px;--sh:.08;width:min(250px,100%);background:var(--surface);border-radius:var(--rad);padding:var(--pad);display:flex;flex-direction:column;gap:var(--gap);box-shadow:0 1px 2px rgba(0,0,0,var(--sh)),0 8px 24px rgba(0,0,0,calc(var(--sh) * .8))}
.dtx-tg{align-self:flex-start}
.dtx-pr{display:flex;align-items:baseline;gap:6px}
.dtx-pr b{font-size:28px;font-weight:600;letter-spacing:-.02em}
.dtx-pr span{font-size:12px}
.dtx-li{display:flex;flex-direction:column;gap:6px;font-size:13px;color:var(--fg2)}
.dtx-li span{display:flex;align-items:center;gap:7px}
.dtx-li svg{color:var(--accent)}
.dtx-cta{width:100%;border-radius:calc(var(--rad) * .6)}
.dtx-insp{padding:14px;display:flex;flex-direction:column;gap:12px;min-width:0}
.dtx-ih{display:flex;align-items:baseline;justify-content:space-between;font-size:13.5px}
.dtx-ih b{font-weight:500}
.dtx-st{font-size:12px}
.dtx-rows{display:flex;flex-direction:column;gap:10px}
.dtx-r{display:grid;grid-template-columns:62px 1fr 40px;align-items:center;gap:10px;font-size:12.5px;color:var(--fg2)}
.dtx-r .v{text-align:right;color:var(--fg);font-size:12px}
.dtx-r.hot .v{color:var(--accent)}
.dtx-sl{position:relative;height:22px;display:flex;align-items:center;cursor:pointer;touch-action:none}
.dtx-sl::before{content:"";position:absolute;left:0;right:0;height:4px;border-radius:2px;background:var(--line)}
.dtx-sl .f{position:absolute;left:0;height:4px;border-radius:2px;background:var(--accent)}
.dtx-sl .k{position:absolute;width:14px;height:14px;margin-left:-7px;border-radius:50%;background:#fff;box-shadow:0 0 0 1px var(--line),0 1px 3px rgba(0,0,0,.18);transition:transform .2s}
.dtx-sl:hover .k,.dtx-sl.drag .k,.dtx-sl:focus-visible .k{transform:scale(1.15)}
.dtx-sl:focus-visible{outline-offset:4px}
.dtx-go{align-self:stretch;margin-top:auto}
.dtx-go.busy{pointer-events:none}
.dtx-note{font-size:12px;color:var(--fg2);padding:8px 10px;border-radius:10px;background:var(--accent-bg);line-height:1.45}

DM.def('design-tuner', (r, c) => {
  r.innerHTML = r.innerHTML.replace(/\{c\}/g, I('check','xs')).replace('{wand}', I('wand','xs'));
  const card = $('.dtx-card', r), rows = $('.dtx-rows', r), st = $('.dtx-st', r), go = $('.dtx-go', r);
  const P = [
    { k:'rad', n:'Radius', min:0, max:28, v:16, u:'px', t:20 },
    { k:'pad', n:'Padding', min:8, max:32, v:18, u:'px', t:24 },
    { k:'gap', n:'Spacing', min:4, max:24, v:12, u:'px', t:14 },
    { k:'sh', n:'Shadow', min:0, max:.2, v:.08, u:'', t:.05, f:2 }
  ];
  rows.innerHTML = P.map(p => `<div class="dtx-r" data-k="${p.k}"><span>${p.n}</span><div class="dtx-sl" role="slider" tabindex="0" aria-label="${p.n}" aria-valuemin="${p.min}" aria-valuemax="${p.max}"><span class="f"></span><span class="k"></span></div><span class="v num"></span></div>`).join('');
  function set(p, v){ p.v = Math.max(p.min, Math.min(p.max, v)); const pc = (p.v - p.min) / (p.max - p.min) * 100; const row = $(`[data-k="${p.k}"]`, rows);
    $('.f', row).style.width = pc + '%'; $('.k', row).style.left = pc + '%'; $('.v', row).textContent = p.f ? p.v.toFixed(p.f) : Math.round(p.v) + p.u;
    card.style.setProperty('--' + p.k, p.f ? p.v : Math.round(p.v) + 'px'); $('.dtx-sl', row).setAttribute('aria-valuenow', p.f ? p.v.toFixed(p.f) : Math.round(p.v)); }
  P.forEach(p => {
    set(p, p.v); const sl = $(`[data-k="${p.k}"] .dtx-sl`, rows);
    const at = e => { const b = sl.getBoundingClientRect(); set(p, p.min + (p.max - p.min) * Math.max(0, Math.min(1, (e.clientX - b.left) / b.width))); };
    sl.onpointerdown = e => { sl.setPointerCapture(e.pointerId); sl.classList.add('drag'); at(e); swap(st, 'Edited by you'); sl.onpointermove = at; };
    sl.onpointerup = sl.onpointercancel = () => { sl.classList.remove('drag'); sl.onpointermove = null; };
    sl.onkeydown = e => { const k = { ArrowRight:1, ArrowUp:1, ArrowLeft:-1, ArrowDown:-1 }[e.key]; if (!k) return; e.preventDefault(); set(p, p.v + k * (p.f ? .01 : 1)); swap(st, 'Edited by you'); };
  });
  let note;
  go.onclick = () => c.run(async () => {
    go.classList.add('busy'); go.innerHTML = '<span class="think on"><i></i><i></i><i></i><i></i></span>Tuning'; swap(st, 'Agent is tuning'); if (note) note.remove();
    for (const p of P){ const row = $(`[data-k="${p.k}"]`, rows); row.classList.add('hot'); await tween(p.v, p.t, 650, x => set(p, x)); await c.wait(120); row.classList.remove('hot'); }
    note = html('<div class="dtx-note">Matched the 4px grid and your card tokens. Softer shadow so the CTA leads.</div>'); go.before(note); enter(note);
    go.classList.remove('busy'); go.innerHTML = I('wand','xs') + 'Tune again'; swap(st, 'Tuned by agent');
    P.forEach(p => { const o = p.t; p.t = p.k === 'rad' ? (o === 20 ? 12 : 20) : p.k === 'pad' ? (o === 24 ? 20 : 24) : p.k === 'gap' ? (o === 14 ? 10 : 14) : (o === .05 ? .1 : .05); });
  });
  // the preview lets the agent tune once on its own, unless you reach for a slider or the button first
  let mine = false; c.on(r, 'pointerdown', e => { if (e.isTrusted) mine = true; }, true); c.on(r, 'keydown', () => mine = true, true);
  c.later(1600, () => { if (!mine) go.click(); });
});
